import { ChangeDetectionStrategy, Component, inject, signal, ViewEncapsulation } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { DIALOG_DATA } from '../../../../../shared/dialog/dialog-tokens';
import { DialogRef, DialogCloseDirective } from '../../../../../shared/dialog/dialog-ref';
import { TopicIdeationService } from '../../../../../core/services/topic-ideation.service';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { InitialsComponent } from '../../../../../shared/components/initials/initials.component';
import { InputComponent } from '../../../../../shared/components/input/input.component';
import { DropdownComponent } from '../../../../../shared/components/dropdown/dropdown.component';
import { Idea } from '../../../../../core/interfaces/idea';

export interface IdeaReportData {
  idea: Idea;
  ideationId: string;
  topicId: string;
}

@Component({
  selector: 'app-idea-report',
  standalone: true,
  imports: [
    ReactiveFormsModule,
    TranslateModule,
    IconComponent,
    InitialsComponent,
    InputComponent,
    DropdownComponent,
    DialogCloseDirective,
  ],
  template: `
    <div class="dialog_wrap">
      <div class="dialog">
        <div class="dialog_header warning">
          <div class="header_with_icon">
            <div class="icon_notification">
              <svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                <rect width="40" height="40" rx="20" fill="#F39129" />
                <path
                  d="M19.0645 8C18.4876 8 18.0304 8.48668 18.0664 9.06238L18.9414 23.0624C18.9743 23.5894 19.4114 24 19.9395 24H20.0605C20.5886 24 21.0257 23.5894 21.0586 23.0624L21.9336 9.06238C21.9696 8.48668 21.5124 8 20.9355 8H19.0645Z"
                  fill="white"
                />
                <path
                  d="M20 31C21.1046 31 22 30.1046 22 29C22 27.8954 21.1046 27 20 27C18.8954 27 18 27.8954 18 29C18 30.1046 18.8954 31 20 31Z"
                  fill="white"
                />
              </svg>
            </div>
            <h4 class="title">{{ 'COMPONENTS.IDEA_REPORT.HEADING' | translate }}</h4>
          </div>
          <div class="dialog_close">
            <button type="button" class="btn_dialog_close icon" dialogClose [aria-label]="'CONTROL.CLOSE' | translate">
              <cos-icon name="nav-close"></cos-icon>
            </button>
          </div>
        </div>
        <div class="dialog_content">
          <div class="dialog_info_wrap">
            <div class="dialog_info row">
              <div class="delete_info_button_wrap">
                <div class="delete_info_text">{{ 'COMPONENTS.IDEA_REPORT.MESSAGE_MAIN' | translate }}</div>
              </div>
              <div class="profile_image_wrap">
                @if (data.idea.author?.imageUrl) {
                  <img class="profile_image" [src]="data.idea.author.imageUrl" alt="" />
                } @else {
                  <div class="profile_image_filler">
                    <cos-initials [name]="data.idea.author?.name || ''"></cos-initials>
                  </div>
                }
              </div>
              <div class="bold" [innerHTML]="data.idea.author?.name || ''"></div>
            </div>
          </div>

          <form [formGroup]="report">
            <cos-input [placeholder]="'COMPONENTS.IDEA_REPORT.LABLE_REASON' | translate">
              <cos-dropdown selection>
                <div selection class="selected_item">{{ 'TXT_REPORT_TYPES_' + report.get('type')?.value?.toUpperCase() | translate }}</div>
                <div options>
                  @for (type of reportTypes; track type) {
                    <div class="option" (click)="selectReportType(type)" (keydown.enter)="selectReportType(type)" role="option" tabindex="0">
                      {{ 'TXT_REPORT_TYPES_' + type.toUpperCase() | translate }}
                    </div>
                  }
                </div>
              </cos-dropdown>
            </cos-input>

            <cos-input
              [placeholder]="'COMPONENTS.IDEA_REPORT.PLACEHOLDER_REPORT_TEXT' | translate"
              [hasError]="!!(report.get('text')?.touched && report.get('text')?.invalid)"
              [errorMessage]="'COMPONENTS.IDEA_REPORT.ERROR_TEXT' | translate"
            >
              <textarea formControlName="text" [placeholder]="'COMPONENTS.IDEA_REPORT.PLACEHOLDER_REPORT_TEXT' | translate" [maxlength]="2048" rows="5"></textarea>
            </cos-input>
          </form>
        </div>
        <div class="dialog_content no_footer">
          <div class="button_wrap">
            <button type="button" class="btn_big_submit" [class.disabled]="report.invalid" (click)="doReport()">
              {{ 'COMPONENTS.IDEA_REPORT.BTN_SUBMIT' | translate }}
            </button>
            <button type="button" class="btn_link" dialogClose>{{ 'COMPONENTS.IDEA_REPORT.BTN_CANCEL' | translate }}</button>
          </div>
        </div>
        <div class="dialog_footer"></div>
      </div>
    </div>
  `,
  styles: [`
    .dialog_wrap {
      max-width: 600px;
      width: 100%;
      background: white;
      border-radius: 4px;
      overflow: hidden;
    }

    .dialog_header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 16px 24px;
      background: #fdf2f2;
      border-bottom: 1px solid #f9dcdc;

      &.warning {
        background: #fff9f2;
        border-bottom: 1px solid #ffe8cc;
      }

      .header_with_icon {
        display: flex;
        align-items: center;
        gap: 16px;

        .icon_notification {
          flex-shrink: 0;
        }

        .title {
          margin: 0;
          font-size: 18px;
          font-weight: 700;
          color: #2c3b47;
        }
      }

      .dialog_close {
        cursor: pointer;
        color: #727c84;
        display: flex;

        &:hover {
          color: #2c3b47;
        }
      }
    }

    .dialog_content {
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 16px;

      .dialog_info_wrap {
        margin-bottom: 16px;

        .dialog_info {
          display: flex;
          align-items: center;
          gap: 12px;

          .delete_info_text {
            font-size: 14px;
            color: #727c84;
          }

          .profile_image_wrap {
            .profile_image {
              width: 32px;
              height: 32px;
              border-radius: 50%;
            }

            .profile_image_filler {
              cos-initials {
                width: 32px;
                height: 32px;
                font-size: 12px;
              }
            }
          }

          .bold {
            font-weight: 700;
            color: #2c3b47;
          }
        }
      }

      form {
        display: flex;
        flex-direction: column;
        gap: 16px;
      }

      &.no_footer {
        padding-top: 0;
      }

      .button_wrap {
        display: flex;
        justify-content: flex-end;
        align-items: center;
        gap: 24px;

        .btn_big_submit {
          background: #ef4025;
          color: white;
          border: none;
          padding: 12px 32px;
          border-radius: 4px;
          font-weight: 700;
          cursor: pointer;

          &:hover:not(.disabled) {
            background: #d33019;
          }

          &.disabled {
            opacity: 0.5;
            cursor: not-allowed;
          }
        }

        a {
          cursor: pointer;
          color: #1168a8;
          font-weight: 600;
          text-decoration: underline;

          &:hover {
            text-decoration: none;
          }
        }
      }
    }

    .selected_item {
      font-size: 14px;
      color: #2c3b47;
    }

    .option {
      padding: 12px 16px;
      cursor: pointer;
      font-size: 14px;
      &:hover {
        background: #f4f6f8;
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None
})
export class IdeaReportComponent {
  public data = inject<IdeaReportData>(DIALOG_DATA);
  private dialogRef = inject(DialogRef);
  private TopicIdeationService = inject(TopicIdeationService);

  reportTypes = Object.keys(this.TopicIdeationService.IDEA_REPORT_TYPES);
  errors = signal<Record<string, string[]> | null>(null);

  report = new FormGroup({
    type: new FormControl(this.reportTypes[0], Validators.required),
    text: new FormControl('', Validators.required),
    topicId: new FormControl(this.data.topicId),
    ideaId: new FormControl(this.data.idea.id),
    ideationId: new FormControl(this.data.ideationId),
  });

  selectReportType(type: string) {
    this.report.get('type')?.setValue(type);
  }

  doReport() {
    if (this.report.invalid) return;

    this.TopicIdeationService.reportIdea({
      type: this.report.value.type!,
      text: this.report.value.text ?? undefined,
      topicId: this.data.topicId,
      ideaId: this.data.idea.id,
      ideationId: this.data.ideationId
    }).subscribe({
      next: () => {
        this.dialogRef.close();
      },
      error: (res) => {
        this.errors.set(res.errors);
      },
    });
  }
}

import { Component, input, output, signal, computed, model, effect, ChangeDetectionStrategy } from '@angular/core';
import { trigger, state, style, transition, animate } from '@angular/animations';
import { DropdownComponent } from '../dropdown/dropdown.component';
import { SearchInputComponent } from '../search-input/search-input.component';
import { IconComponent } from '../icon/icon.component';
import { TranslateModule } from '@ngx-translate/core';
import { NgClass, TitleCasePipe } from '@angular/common';

export interface FilterOption {
  title: string;
  value: string;
}

export interface FilterConfig {
  key: string;
  placeholder: string;
  selectedValue: string;
  items: FilterOption[];
}

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'app-list-filter-toolbar',
  standalone: true,
  imports: [DropdownComponent, SearchInputComponent, IconComponent, TranslateModule, NgClass, TitleCasePipe],
  template: `
    <div class="list-filter-toolbar mobile_hidden tablet_hidden" role="toolbar" aria-label="List Filters">
      <div class="options_area">
        @for (row of mainRows(); track $index) {
          <div class="options_row">
            @for (filter of row; track filter.key) {
              <cos-dropdown
                class="toolbar-dropdown"
                [placeholder]="filter.placeholder | translate">
                <ng-container selection>
                  <span class="selected-item">{{ getActiveFilterText(filter) | translate }}</span>
                </ng-container>
                <ng-container options>
                  @for (option of filter.items; track option.value) {
                    <div class="option" (click)="selectFilter(filter.key, option.value)" (keydown.enter)="selectFilter(filter.key, option.value)" tabindex="0" role="option">
                      {{ option.title | translate }}
                    </div>
                  }
                </ng-container>
              </cos-dropdown>
            }
          </div>
        }

        <div class="extra_area" [@slideInOut]="moreFilters() ? 'open' : 'closed'">
          @for (row of extraRows(); track $index) {
            <div class="options_row">
              @for (item of row; track ($any(item).key || 'search')) {
                @if (item.type === 'search') {
                  <app-search-input
                    class="toolbar-search"
                    [placeholder]="searchPlaceholder()"
                    [value]="searchValue()"
                    (valueChange)="searchValue.set($event)"
                  ></app-search-input>
                } @else {
                  <cos-dropdown
                    class="toolbar-dropdown"
                    [placeholder]="$any(item).placeholder | translate">
                    <ng-container selection>
                      <span class="selected-item">{{ getActiveFilterText($any(item)) | translate }}</span>
                    </ng-container>
                    <ng-container options>
                      @for (option of ($any(item).items); track option.value) {
                        <div class="option" (click)="selectFilter($any(item).key, option.value)" (keydown.enter)="selectFilter($any(item).key, option.value)" tabindex="0" role="option">
                          {{ option.title | translate }}
                        </div>
                      }
                    </ng-container>
                  </cos-dropdown>
                }
              }
            </div>
          }
        </div>
      </div>
      <div class="filter_control_buttons">
        <button class="btn_big_secondary" (click)="moreFilters.update(v => !v)" aria-label="Toggle Filters">
          <cos-icon [name]="moreFilters() ? 'chevron-up' : 'chevron-down'"></cos-icon>
        </button>
        @if (hasActiveFilters()) {
          <button class="btn_big_secondary" (click)="clearAll()" aria-label="Reset Filters">
            <cos-icon name="refresh"></cos-icon>
          </button>
        }
      </div>
    </div>

    <!-- Mobile specific filters styling matching citizenos-fe -->
    <div class="mobile_show tablet_show" id="mobile_filters">
      <div class="dropdown mobile_filters_selection" [ngClass]="{'dropdown_active': mobileFiltersOpen()}">
        <div class="selection" (click)="mobileFiltersOpen.set(!mobileFiltersOpen())">
          <div class="selected_item">{{ 'COMPONENTS.PUBLIC_TOPICS.LBL_FILTER' | translate | titlecase }}</div>
          <button class="btn_medium_plain icon">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M17 10L12 15L7 10" stroke="#2C3B47" stroke-width="2" stroke-linecap="round" />
            </svg>
          </button>
        </div>

        <div class="options filter_options">
          @for (filter of allFilters(); track filter.key) {
            <div class="filter_option" (click)="activeMobileFilter.set(filter.key)">
              <span>{{ filter.placeholder | translate }}</span>
              <a class="bold">
                @if (filter.selectedValue === 'all' || filter.selectedValue === '') {
                  <span>{{ 'VIEWS.GROUP.FILTER_ALL' | translate }}</span>
                }
                @if (filter.selectedValue !== 'all' && filter.selectedValue !== '') {
                  <span>{{ getActiveFilterText(filter) | translate }}</span>
                }
                <cos-icon name="chevron-right" [size]="24"></cos-icon>
              </a>
            </div>
          }
        </div>
      </div>

      @if (activeMobileFilter() !== null) {
        <div class="overlay" (click)="activeMobileFilter.set(null)"></div>
        <div class="mobile_filters_wrap active">
          <div class="options button_options">
            <label class="checkbox" (click)="selectFilter(activeMobileFilter()!, 'all')">
              <span>{{ 'TXT_TOPIC_STATUS_ALL' | translate | titlecase }}</span>
              <input type="radio" [name]="activeMobileFilter()" [checked]="getActiveFilter(activeMobileFilter()!)?.selectedValue === 'all' || getActiveFilter(activeMobileFilter()!)?.selectedValue === ''">
              <span class="checkmark"></span>
            </label>
            @if (getActiveFilter(activeMobileFilter()!); as activeF) {
              @for (option of activeF.items; track option.value) {
                <label class="checkbox" (click)="selectFilter(activeF.key, option.value)">
                  <span>{{ option.title | translate }}</span>
                  <input type="radio" [name]="activeF.key" [checked]="activeF.selectedValue === option.value">
                  <span class="checkmark"></span>
                </label>
              }
            }
            <button type="button" class="btn_medium_secondary" (click)="activeMobileFilter.set(null)">{{ 'COMPONENTS.PUBLIC_TOPICS.BTN_APPLY' | translate }}</button>
          </div>
        </div>
      }
    </div>
  `,
  animations: [
    trigger('slideInOut', [
      state('closed', style({
        height: '0px',
        opacity: 0,
        overflow: 'hidden',
        visibility: 'hidden',
        marginTop: '0px'
      })),
      state('open', style({
        height: '*',
        opacity: 1,
        visibility: 'visible',
        marginTop: '16px'
      })),
      transition('open <=> closed', animate('300ms ease-in-out'))
    ])
  ],
  styles: [`
    .list-filter-toolbar {
      display: flex;
      flex-direction: row;
      align-items: flex-start;
      gap: 16px;
      background: var(--color-surfaces);
      border-radius: 16px;
      padding: 16px;
      width: 100%;
      margin-bottom: 24px;
      box-sizing: border-box;
    }
    .options_area {
      flex: 1;
      min-width: 0;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }
    .options_row {
      width: 100%;
      display: flex;
      flex-flow: row wrap;
      gap: 16px;
      position: relative;
    }
    .toolbar-dropdown {
      flex: 1;
      min-width: calc(25% - 12px);
    }
    .toolbar-search {
      display: flex;
      flex: 2;
      min-width: calc(50% - 12px);
    }
    .extra_area {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }
    .font-bold {
      font-weight: 600;
    }
    .option {
      padding: 10px 16px;
      cursor: pointer;
      font-size: 14px;
      color: var(--color-text);
    }
    .option:hover {
      background: var(--color-secondary);
    }
    .filter_control_buttons {
      display: flex;
      flex-direction: column;
      gap: 8px;
      flex-shrink: 0;
    }
    .btn_big_secondary {
      background: var(--color-background);
      border: 1px solid var(--color-background);
      border-radius: 50%;
      width: 48px;
      height: 48px;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      color: var(--color-link);
      transition: background 0.2s;
    }
    .btn_big_secondary:hover {
      background: var(--color-background-hover);
    }

    @media (max-width: 1024px) {
      .toolbar-dropdown, .toolbar-search {
        min-width: calc(50% - 12px);
      }
    }

    /* Mobile specific filters styling matching citizenos-fe */
    .filter_dropdown {
      display: none;
      margin-bottom: 24px;
    }
    @media (max-width: 1023px) {
      .mobile_hidden {
        display: none !important;
      }
      .mobile_show {
        display: block !important;
      }
      .filter_dropdown {
        display: block;
      }
      .mobile_filters_selection {
        background: var(--color-surfaces);
        border-radius: 8px;
        position: relative;
      }
      .mobile_filters_selection.dropdown_active .options {
        display: block;
      }
      .mobile_filters_selection.dropdown_active .selection svg {
        transform: rotate(180deg);
      }
      .mobile_filters_selection .selection {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 16px;
        cursor: pointer;
        font-weight: 600;
      }
      .mobile_filters_selection .selection .btn_medium_plain {
        background: none;
        border: none;
        cursor: pointer;
      }
      .filter_options {
        display: none;
        padding: 0 16px 16px;
      }
      .filter_option {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 0;
        border-bottom: 1px solid var(--color-border);
      }
      .filter_option:last-child {
        border-bottom: none;
      }
      .filter_option .bold {
        display: flex;
        align-items: center;
        gap: 8px;
        font-weight: 600;
        cursor: pointer;
        color: var(--color-link);
      }

      .overlay {
        position: fixed;
        cursor: pointer;
        z-index: 9999;
        background-color: rgba(44, 59, 71, 0.8);
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
      }
      .mobile_filters_wrap {
        display: flex;
        position: fixed;
        bottom: -200px;
        padding: 16px;
        left: 0;
        background-color: var(--color-surfaces);
        z-index: 9999999;
        width: 100%;
        max-height: 100%;
        box-sizing: border-box;
        border-radius: 16px 16px 0 0;
        box-shadow: 0px 8px 20px 0px rgba(220, 231, 240, 0.3),
          0px 12px 16px 0px rgba(50, 85, 112, 0.1);
        transition: bottom 0.2s ease-in;
        visibility: hidden;
      }
      .mobile_filters_wrap.active {
        bottom: 0;
        visibility: visible;
      }
      .mobile_filter {
        background: var(--color-surfaces);
        border-radius: 8px;
        margin-top: 16px;
        padding: 16px;
      }
      .button_options {
        display: flex;
        flex-direction: column;
        gap: 16px;
        width: 100%;
        max-height: 80vh;
        overflow-y: auto;
      }
      .checkbox {
        display: flex;
        justify-content: flex-end;
        align-items: center;
        gap: 8px;
        position: relative;
        cursor: pointer;
        user-select: none;
        min-height: 24px;
        flex-direction: row-reverse;
        flex-wrap: wrap;
        width: 100%;
      }
      .checkbox span {
        max-width: calc(100% - 40px);
      }
      .checkbox input {
        position: absolute !important;
        opacity: 0;
        cursor: pointer;
        height: 0;
        width: 0;
      }
      .checkmark {
        height: 24px;
        width: 24px;
        min-width: 24px;
        border: 1px solid var(--color-border);
        border-radius: 8px;
        position: relative;
      }
      .checkbox:hover input ~ .checkmark {
        background-color: var(--color-background-hover);
      }
      .checkbox input:checked ~ .checkmark {
        background-color: var(--color-primary);
        border-color: var(--color-primary);
      }
      .checkmark:after {
        content: "";
        position: absolute;
        display: none;
      }
      .checkbox input:checked ~ .checkmark:after {
        display: block;
      }
      .checkbox .checkmark:after {
        left: 7px;
        top: 3px;
        width: 5px;
        height: 10px;
